41	    // DRAFT until issued, reads SENT once issued but unpaid, PARTIAL once some (but not all) of the
42	    // amount is paid, and PAID once the payments cover the amount. Derived here so the status always
43	    // reflects the payments on file.
44	    private static final String DERIVED_STATUS =
45	            "CASE WHEN i.status = 'VOID' THEN 'VOID'"
46	                    + " WHEN i.status = 'DRAFT' THEN 'DRAFT'"
47	                    + " WHEN " + AMOUNT_SUM + " > 0 AND " + PAID_SUM + " >= " + AMOUNT_SUM
48	                    + " THEN 'PAID'"
49	                    + " WHEN " + PAID_SUM + " > 0 THEN 'PARTIAL'"
50	                    + " ELSE 'SENT' END";
