52	    public List<Invoice> findByProject(long projectId) {
53	        return jdbc.query(
54	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
55	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct"
56	                        + " FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
57	                MAPPER, projectId);
