64	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct"
65	                        + " FROM invoices i WHERE i.project_id = ?"
66	                        + " ORDER BY i.due_date ASC NULLS LAST, i.id",
