77	    private static final String LISTING_SELECT =
78	            "SELECT i.id AS id, i.project_id AS project_id, p.name AS project_name, "
79	                    + AMOUNT_SUM + " AS amount, " + DERIVED_STATUS + " AS status FROM invoices i"
