114	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
115	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct"
116	                        + " FROM invoices i WHERE i.id = ?",
